import java.util.*;

class Solution {
  public double minAreaFreeRect(int[][] points) {
    int n = points.length;
    Map<String, List<int[]>> map = new HashMap<>();
    for (int i = 0; i < n; i++)
      for (int j = i + 1; j < n; j++) {
        int cx = points[i][0] + points[j][0], cy = points[i][1] + points[j][1];
        int dx = points[i][0] - points[j][0], dy = points[i][1] - points[j][1];
        String key = cx + "," + cy + "," + (dx * dx + dy * dy);
        map.computeIfAbsent(key, k -> new ArrayList<>()).add(new int[] {i, j});
      }
    double ans = Double.MAX_VALUE;
    for (List<int[]> list : map.values())
      for (int a = 0; a < list.size(); a++)
        for (int b = a + 1; b < list.size(); b++) {
          int[] p = list.get(a), q = list.get(b);
          if (p[0] == q[0] || p[0] == q[1] || p[1] == q[0] || p[1] == q[1]) continue;
          double x = points[p[0]][0] - points[q[0]][0], y = points[p[0]][1] - points[q[0]][1];
          double u = points[p[1]][0] - points[q[0]][0], v = points[p[1]][1] - points[q[0]][1];
          ans = Math.min(ans, Math.abs(x * v - y * u));
        }
    return ans == Double.MAX_VALUE ? 0 : ans;
  }
}
